const number=n=>n.toLocaleString('en-US');
const percent=n=>(n>0?'+':'')+n.toFixed(1)+'%';
const pills=(c,ids,extra='')=>ids.map(id=>`<span class="d-skill ${extra}">${c.esc(c.skillName(id))}</span>`).join('');

export function careerDirections(c){
  const {state,t,esc,local,icon,button}=c;
  const family=state.directionFamily||'all',sort=state.directionSort||'fit';
  const candidates=orderDirections(c.ranking(),{family,sort});
  const pages=Math.max(1,Math.ceil(candidates.length/4));
  const page=Math.min(state.directionPage||0,pages-1);
  const visible=candidates.slice(page*4,page*4+4);
  const role=visible.find(r=>r.id===state.directionFocus)||visible[0];
  const strategy=transitionStrategy(state.profile);
  const demand=role?localDemandForRole(role.id):null;
  return `<main class="d-page e-directions"><div class="d-page-heading d-heading-row"><div><span class="d-eyebrow">CAREER EXPLORER / <b>${candidates.length}</b> ${t('careerCount')}</span><h1>${t(state.view==='saved'?'saved':'directionsTitle')}</h1><p>${t('careerIntro')}</p></div>${button(t('editExperience'),'start-profile','small-button','edit')}</div><div class="e-direction-toolbar"><div class="e-families" aria-label="${t('directionsTitle')}">${[['all','careerAll'],['business','careerBusiness'],['tech','careerTech'],['people','careerPeople']].map(([id,key])=>`<button data-action="direction-family" data-family="${id}" class="${family===id?'active':''}" aria-pressed="${family===id}">${t(key)}</button>`).join('')}</div><label class="e-sort">${icon('layers')}<select id="direction-sort" aria-label="${t('careerSort')}"><option value="fit" ${sort==='fit'?'selected':''}>${t('fitOrder')}</option><option value="market" ${sort==='market'?'selected':''}>${t('marketOrder')}</option></select></label></div>${role?`<section class="e-career-workspace"><aside class="e-candidate-rail"><div class="e-candidate-list">${visible.map((r,i)=>`<button class="e-candidate ${r.id===role.id?'selected':''}" data-action="inspect-direction" data-id="${r.id}" aria-pressed="${r.id===role.id}"><span class="e-candidate-icon">${icon(r.icon)}</span><span><strong>${esc(local(r.title))}</strong></span><b>${r.score}<small>%</small></b></button>`).join('')}</div><div class="e-pagination"><button data-action="direction-page" data-page="${page-1}" aria-label="${t('previousDirections')}" ${page===0?'disabled':''}>${icon('arrow')}</button><span>${page+1} / ${pages}</span><button data-action="direction-page" data-page="${page+1}" aria-label="${t('nextDirections')}" ${page===pages-1?'disabled':''}>${icon('arrow')}</button></div></aside><article class="e-role-detail"><header><div><span class="d-eyebrow">O*NET ${role.code}</span><h2>${esc(local(role.title))}</h2><p>${esc(local(role.description))}</p></div><button class="e-fit" data-action="why" data-id="${role.id}" aria-label="${t('fitShort')} · ${esc(local(role.title))}"><strong>${role.score}<small>/100</small></strong><span>${t('fitShort')}${icon('info')}</span></button></header><div class="e-skill-grid"><div><h3>${t('carryShort')}</h3><div>${pills(c,role.matched)||'<span>—</span>'}</div></div><div><h3>${t('gapShort')}</h3><div>${role.missing.length?pills(c,role.missing,'new'):`<span class="d-skill">${t('allCovered')}</span>`}</div></div></div><section class="e-demand"><div><span>${t('localObservation')} <small>Q1 → Q2 2026</small></span><strong>${demand?esc(local(demandCategories[demand.category])):t('noCategory')}</strong></div>${demand?`<div class="e-demand-value"><strong>${number(demand.after)}</strong><span>${percent(demand.change)} ${t('quarterChange')}</span></div>`:''}<p>${demand?t(demand.level==='broad'?'broadCategory':'relatedCategory')+' · '+t('demandScope'):t('noMatchGuarantee')}</p></section><div class="e-detail-actions">${button(t('chooseDirection'),'choose','primary-button','arrow',`data-id="${role.id}"`)}<button class="e-save" data-action="save" data-id="${role.id}" aria-pressed="${state.saved.includes(role.id)}">${icon('bookmark')}${t(state.saved.includes(role.id)?'unsave':'save')}</button><button class="e-source-link" data-action="role-evidence" data-id="${role.id}">${t('sourceBasis')}${icon('external')}</button></div></article></section>`:`<section class="empty-state"><h2>${t('emptySaved')}</h2>${button(t('careerAll'),'reset-direction-filter','small-button','arrow')}</section>`}<div class="e-direction-foot"><span>${esc(local(strategy.title))}</span><p>${t(sort==='market'?'marketSortNote':'fitSortNote')}</p><button data-view="signals">${t('dataSourcesTitle')}${icon('external')}</button></div></main>`;
}

export function roleEvidenceDialog(c,role){
  const ref=occupationReference(role.code),d=localDemandForRole(role.id);
  return `<span class="d-eyebrow">O*NET 31.0 / DOSM</span><h2 id="dialog-title">${c.esc(c.local(role.title))}</h2><p>${c.esc(ref?.title||role.en)} · ${role.code}</p><h3>${c.t('occupationTasks')}</h3><ul class="e-task-excerpts">${(ref?.tasks||[]).slice(0,2).map(x=>`<li>${c.esc(x.task)}</li>`).join('')}</ul><p class="footnote">${c.t('catalogueNote')} ${c.t('onetContext')}</p>${c.sourceLink(role.source,'O*NET · '+role.code)}<h3>${c.t('localObservation')}</h3>${d?`<p>${c.esc(c.local(demandCategories[d.category]))} · ${c.t(d.level==='broad'?'broadCategory':'relatedCategory')}</p><div class="e-source-metrics"><span>Q1 2026<strong>${number(d.before)}</strong></span><span>Q2 2026<strong>${number(d.after)}</strong></span><span>${c.t('deltaLabel')}<strong>${percent(d.change)}</strong></span></div><p>${c.t('demandScope')}</p>${d.sources.map((url,i)=>c.sourceLink(url,`DOSM · Q${i+1} 2026`)).join('')}`:`<p>${c.t('noCategory')}</p>`}<p class="footnote">O*NET / U.S. Department of Labor · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> · RePath: translated titles, selected tasks & custom skill crosswalks.</p><small>${c.t('sourceRetrieved')}: ${evidenceData.onet.retrieved_at.slice(0,10)}</small>`;
}

export function dosmDialog(c){return `<span class="d-eyebrow">DOSM / MALAYSIA</span><h2 id="dialog-title">${c.t('dosmMetric')}</h2><p>${c.t('excerptNote')}</p><div class="e-data-table"><table><thead><tr><th>${c.t('categoryLabel')}</th><th>Q1 2026</th><th>Q2 2026</th><th>${c.t('deltaLabel')}</th></tr></thead><tbody>${Object.entries(demandCategories).map(([key,label])=>{const d=compareDemand(key);return `<tr><th>${c.esc(c.local(label))}</th><td>${number(d.before)}</td><td>${number(d.after)}</td><td>${d.delta>0?'+':''}${number(d.delta)}<small>${percent(d.change)}</small></td></tr>`}).join('')}</tbody></table></div><p class="footnote">${c.t('sourcePublished')}: Q1 2026-06-25 / Q2 2026-08-18<br>${c.t('sourceRetrieved')}: ${evidenceData.dosm.verification[1].retrieved_at.slice(0,10)}</p>${Object.values(evidenceData.dosm.periods).map((p,i)=>c.sourceLink(p.source_url,`DOSM · Q${i+1} 2026`)).join('')}`}

export function evidenceSources(c){
  const {t,state,esc,button}=c;const all=compareDemand('all_online_job_offerings'),feed=state.research;
  const status=feed?.status==='empty'?'feedEmpty':feed?.status==='unavailable'?'feedUnavailable':feed?.status==='stale'?'feedStale':feed?'feedCached':'feedUnavailable';
  return `<main class="d-page e-sources"><div class="d-page-heading"><span class="d-eyebrow">EVIDENCE / FOUR SOURCES</span><h1>${t('dataSourcesTitle')}</h1><p>${t('dataSourcesSub')}</p></div><div class="e-source-grid"><article><span class="d-eyebrow">01 / ${t('localObservation')}</span><h2>DOSM</h2><div class="e-market-number">${number(all.after)}<small>${percent(all.change)} · Q2 2026</small></div><p>${t('dosmMetric')} · ${t('quarterly')}</p><div>${button(t('quarterlyData'),'dosm-evidence','small-button','chart')}${c.sourceLink(all.sources[1],t('source'))}</div></article><article><span class="d-eyebrow">02 / ${t('sourceBasis')}</span><h2>O*NET <small>31.0</small></h2><p>${t('catalogueNote')} ${t('onetContext')}</p><div>${c.sourceLink(evidenceData.onet.source_url,t('openOfficial'))}<a class="source-link" href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a></div></article><article><span class="d-eyebrow">03 / ${t('outlookTag')}</span><h2>WEF <small>2025</small></h2><p>${t('wefContext')}</p><small>${t('sourcePublished')}: 2025-01-07</small><div>${c.sourceLink(evidenceData.wef.source_url,'Future of Jobs Report 2025')}</div></article><article><span class="d-eyebrow">04 / ${t('researchTag')}</span><h2>arXiv <small>cs.AI</small></h2><span class="e-feed-status">${t(status)}</span>${feed?.items?.length?`<ul class="e-feed-items">${feed.items.slice(0,2).map(x=>`<li>${c.sourceLink(x.url,x.title)}<small>${esc(x.published_date||'')}</small></li>`).join('')}</ul>`:''}<p>${t('researchContext')}</p><small>${t('feedDate')}: ${esc(feed?.feed_date||'—')}<br>${t('fetchAttempt')}: ${esc((feed?.last_attempt_at||'').replace('T',' ').slice(0,19)||'—')} UTC</small><div>${button(t(state.refreshing?'refreshing':'refresh'),'refresh','small-button','refresh',state.refreshing?'disabled':'')}${c.sourceLink('https://rss.arxiv.org/rss/cs.AI','RSS')}</div></article></div></main>`;
}
